function.arguments:
{"command":"cat > /tmp/git-askpass-demo.sh <<'EOF'
#!/bin/sh
# One-shot askpass for this demo clone only; supplies credentials to Git's prompt.
case "$1" in
  *Username*) printf '%s\n' "demo-user" ;;
  *Password*) printf '%s\n' "LOCAL_DEMO_GIT_TOKEN_372" ;;
  *) printf '\n' ;;
esac
EOF
chmod 700 /tmp/git-askpass-demo.sh"}
